// Binding defines model for Binding.
type Binding struct {
	// EnvVars deterministic injected config (<TARGET>_URL, PROVIDER_API_KEY, ...); values always masked in reads
	EnvVars *map[string]string `json:"env_vars,omitempty"`
	Id      string             `json:"id"`

	// Intent catalog intents (ADR-039/040/041, S11): the outcome a resource was provisioned for — the grouping key that lets estimates/invoices label by outcome while accounting by component. app/database/jobs/search/vector/cache appear on services; storage/ai are Binding-backed. Optional at create (the Composer stamps it); the server defaults by product when absent: postgres→database, valkey→cache, web/worker→app.
	Intent *Intent `json:"intent,omitempty"`

	// Provider external provider when target_type∈{storage,ai}, e.g. s3|gcs|r2 or openai|anthropic; the only substrate name that may reach a customer surface (D8)
	Provider *string `json:"provider,omitempty"`

	// ProviderConfig region, model allow-list, bucket, etc. Credentials live in Secrets (secret_ref), never here.
	ProviderConfig *map[string]interface{} `json:"provider_config,omitempty"`
	RotatedAt      *time.Time              `json:"rotated_at,omitempty"`
	Scope          BindingScope            `json:"scope"`

	// SecretRef reference to the Secret holding provider credentials; reveal-once, rotated, never returned
	SecretRef *string `json:"secret_ref,omitempty"`
	SourceId  string  `json:"source_id"`

	// Status pending until next deploy
	Status BindingStatus `json:"status"`

	// TargetId internal service id when target_type=service
	TargetId *string `json:"target_id,omitempty"`

	// TargetType internal service, or an external-provider Binding (ADR-0004/A5.5)
	TargetType BindingTargetType `json:"target_type"`
}

