// PostEnvironmentTeardownJSONBody defines parameters for PostEnvironmentTeardown.
type PostEnvironmentTeardownJSONBody struct {
	// Observed the only thing a cell can report about a namespace it was asked to remove. An enum of one, deliberately: a teardown that did not finish is reported by NOT calling this, so the environment stays outstanding and the next tick retries.
	Observed PostEnvironmentTeardownJSONBodyObserved `json:"observed"`
}

// PostEnvironmentTeardownJSONBodyObserved defines parameters for PostEnvironmentTeardown.
type PostEnvironmentTeardownJSONBodyObserved string

// PostReconcileStatusJSONBody defines parameters for PostReconcileStatus.
type PostReconcileStatusJSONBody struct {
	// Conditions reserved (US-1.3): accepted and acknowledged, not yet persisted — the field exists so the agent's wire format is stable before condition storage lands
	Conditions *[]struct {
		Message *string                                     `json:"message,omitempty"`
		Reason  *string                                     `json:"reason,omitempty"`
		Status  PostReconcileStatusJSONBodyConditionsStatus `json:"status"`
		Type    string                                      `json:"type"`
	} `json:"conditions,omitempty"`

	// Event optional one-line note recorded on the spine event
	Event *string `json:"event,omitempty"`

	// ObservedGeneration the generation the cell converged; a report for any generation other than the one desired holds now is rejected (409)
	ObservedGeneration int64  `json:"observed_generation"`
	ServiceId          string `json:"service_id"`

	// Status what the cell OBSERVES about the workload. `suspended` and `deleting` are NOT accepted (422): they are lifecycle states the control plane sets, never things a cell can observe. `gone` means the workload is absent — a completed teardown when the service is deleting, and a workload that vanished while desired still wants it alive otherwise (the row deliberately stays outstanding so the next converge re-creates it). Omit for an observation-only heartbeat: it asserts nothing about status, so it finishes the generation only when the row already rests on a settled status (ready/failed).
	Status *PostReconcileStatusJSONBodyStatus `json:"status,omitempty"`
}

// PostReconcileStatusJSONBodyConditionsStatus defines parameters for PostReconcileStatus.
type PostReconcileStatusJSONBodyConditionsStatus string

// PostReconcileStatusJSONBodyStatus defines parameters for PostReconcileStatus.
type PostReconcileStatusJSONBodyStatus string

